package com.lianxibu.site.service.jobs;
import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.*;
import com.lianxibu.site.repository.jobs.JdbcBacklogHistory;
import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.function.LongSupplier;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** Original readonly readiness and pause proof, persisted intervals retain every uncertain gap. */
public final class BacklogHistoryObservationService {
 private static final int TOTAL=8388608;private final JdbcBacklogHistory db;private final DispatchReadinessService readiness;private final SettingsJdbcStore settings;private final TransactionTemplate reads;private final Clock clock;private final LongSupplier monotonic;private Instant last;private long lastNano;private boolean poisoned;
 public record Change(JdbcBacklogHistory.History before,JdbcBacklogHistory.History next){@Override public String toString(){return "BacklogHistoryChange[redacted]";}}
 public record Observation(Evidence facts,List<Change> changes){public Observation{Objects.requireNonNull(facts);changes=List.copyOf(changes);}@Override public String toString(){return "BacklogHistoryObservation[redacted]";}}
 private record Pending(JdbcBacklogHistory.Root root,JdbcBacklogHistory.History before,Boolean ready,Boolean paused,List<Span> spans){}
 private record Frame(Mutation mutation,List<Pending> roots){}
 public BacklogHistoryObservationService(JdbcBacklogHistory db,DispatchReadinessService readiness,SettingsJdbcStore settings,PlatformTransactionManager tx,Clock clock,LongSupplier monotonic){this.db=Objects.requireNonNull(db);this.readiness=Objects.requireNonNull(readiness);this.settings=Objects.requireNonNull(settings);this.clock=Objects.requireNonNull(clock);this.monotonic=Objects.requireNonNull(monotonic);reads=new TransactionTemplate(Objects.requireNonNull(tx));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(10);}
 public synchronized Observation acquire(){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("backlog facts require an owned readonly snapshot");if(poisoned)return null;
  try{Instant start=clock.instant().truncatedTo(ChronoUnit.MICROS);long nano=monotonic.getAsLong();if(start.getEpochSecond()<0||last!=null&&(start.isBefore(last)||nano<lastNano||Math.abs(Math.subtractExact(Duration.between(last,start).toNanos(),Math.subtractExact(nano,lastNano)))>2000000000L)){poisoned=true;return null;}last=start;lastNano=nano;
   var frame=reads.execute(s->{Mutation mutation=db.mutation();if(mutation!=null&&mutation.changedAt().isAfter(start))throw invalid();var current=settings.current();Boolean paused=current!=null&&current.mappingComplete()?current.aiPaused():null;var pending=new ArrayList<Pending>();int bytes=0;for(var root:db.pending()){if(root.createdAt().isAfter(start)||root.updatedAt().isAfter(start))throw invalid();Boolean ready=false;if(Set.of("queued","waiting_retry").contains(root.state()))try{ready=readiness.preflight(root.id());}catch(RuntimeException missingProof){ready=null;}
     JdbcBacklogHistory.History before=null;boolean broken=false;try{before=db.read(root);}catch(RuntimeException damaged){broken=true;}if(before!=null){bytes=Math.addExact(bytes,JdbcBacklogHistory.bytes(before));if(bytes>TOTAL)throw invalid();}
     var spans=new ArrayList<Span>();if(mutation==null||broken)spans=null;else if(before==null)add(spans,new Span(root.createdAt(),start,null,null));else{
      if(before.readAt().isAfter(start)||before.verifiedAfter().isAfter(start)||before.mutation().epoch().equals(mutation.epoch())&&(before.mutation().sequence()>mutation.sequence()||!before.mutation().startedAt().equals(mutation.startedAt())||before.mutation().changedAt().isAfter(mutation.changedAt()))||!before.mutation().epoch().equals(mutation.epoch())&&!mutation.startedAt().isAfter(before.readAt()))throw invalid();
      spans.addAll(before.spans());add(spans,new Span(before.readAt(),before.verifiedAfter(),null,null));boolean same=before.mutation().equals(mutation)&&before.stamp().equals(root.stamp())&&Objects.equals(before.ready(),ready)&&Objects.equals(before.paused(),paused);
      if(same){Instant from=before.verifiedAfter();if(Boolean.TRUE.equals(ready)&&root.eligibleAt().isAfter(from)){Instant end=root.eligibleAt().isBefore(start)?root.eligibleAt():start;add(spans,new Span(from,end,false,paused));from=end;}add(spans,new Span(from,start,ready,paused));}else add(spans,new Span(before.verifiedAfter(),start,null,null));if(spans.size()>10000){spans.clear();add(spans,new Span(root.createdAt(),start,null,null));}
     }pending.add(new Pending(root,before,ready,paused,spans));}return new Frame(mutation,List.copyOf(pending));});
   Instant finished=clock.instant().truncatedTo(ChronoUnit.MICROS);long done=monotonic.getAsLong();if(finished.isBefore(start)||Duration.between(start,finished).compareTo(Duration.ofSeconds(60))>0||done<nano||Math.abs(Math.subtractExact(Duration.between(start,finished).toNanos(),Math.subtractExact(done,nano)))>2000000000L){poisoned=true;return null;}var entries=new ArrayList<Entry>();var changes=new ArrayList<Change>();int bytes=0;for(var pending:frame.roots()){var root=pending.root();entries.add(new Entry(root.id(),root.priority(),root.state(),root.createdAt(),start,pending.spans()));if(pending.spans()!=null){var after=new JdbcBacklogHistory.History(root.id(),root.createdAt(),start,root.stamp(),frame.mutation(),pending.ready(),pending.paused(),pending.spans(),finished,pending.before()==null?1:pending.before().revision()+1);bytes=Math.addExact(bytes,JdbcBacklogHistory.bytes(after));if(bytes>TOTAL)throw invalid();changes.add(new Change(pending.before(),after));}}
   return new Observation(new Evidence(start,entries,frame.mutation()),changes);
  }catch(RuntimeException unavailable){return null;}
 }
 public void save(Observation observation){if(observation==null)throw invalid();for(var change:observation.changes())db.save(change.before(),change.next());}
 private static void add(List<Span> spans,Span value){if(value.start().equals(value.end())&&!spans.isEmpty())return;if(!spans.isEmpty()){var last=spans.getLast();if(last.end().equals(value.start())&&Objects.equals(last.ready(),value.ready())&&Objects.equals(last.globallyPaused(),value.globallyPaused())){spans.set(spans.size()-1,new Span(last.start(),value.end(),last.ready(),last.globallyPaused()));return;}}spans.add(value);}
 private static IllegalStateException invalid(){return new IllegalStateException("native backlog observation unavailable");}
}
